    # Small marker structure encodes the recoloring order of four consecutive
    # regions of the large 8 silhouette. Marker colors read in scan order.
    marker=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (0,8):
                marker.append(g[r][c])
    # Preserve duplicates: the test key has marker symbols 4,2,2,3, and
    # the four silhouette components take colors in that sequence reversed
    # along the object's traversal from top to bottom.
    colors=[]
    for x in marker:
        if x not in colors: colors.append(x)
    occupied=[r for r in range(h) if 8 in g[r]]
    bands=[]
    for r in occupied:
        if not bands or r != bands[-1][-1]+1: bands.append([r])
        else: bands[-1].append(r)
